import geopandas as gpd
from shapely.geometry import mapping
l=gpd.read_file('/bench/fixtures/join_points.geojson')
z=gpd.read_file('/bench/fixtures/join_zones.geojson')
out=[]
for _,p in l.iterrows():
 for _,q in z.iterrows():
  if p.geometry.within(q.geometry):
   out.append({"type":"Feature","properties":{"point_id":p.point_id,"kind":p.kind,"zone_id":q.zone_id,"zone_name":q.zone_name},"geometry":mapping(p.geometry)})
print(out)
